#!/usr/bin/env python3
"""The check for error-codes/t1. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import json\nfrom tally.errors import TallyError\nreg = json.load(open("errors/registry.json"))\ntry:\n    from tally.customers import make_customer\n    make_customer("C-1", "Acme", "a@acme.io", "Germany")\nexcept TallyError as e:\n    entry = reg["errors"].get(e.name)\n    assert entry is not None, f"{e.name} isn\'t in errors/registry.json"\n    assert entry["code"] == e.code, f"{e.name} raised {e.code}, registered as {entry[\'code\']}"\n    lo, hi = (int(x[1:]) for x in reg["ranges"]["customers"].split("-"))\n    assert lo <= int(e.code[1:]) <= hi, f"{e.code} is outside customers\'s range"\n    assert e.code not in [\'E1001\', \'E1002\', \'E1003\', \'E2001\', \'E2002\', \'E3001\', \'E3002\', \'E4001\', \'E5001\', \'E5002\', \'E6001\', \'E7001\'], f"{e.code} was already taken"\nelse:\n    raise SystemExit("no TallyError was raised")\nfrom tally.customers import make_customer\nmake_customer("C-1", "Acme", "a@acme.io", "DE")'))


if __name__ == "__main__":
    main(check)
